 *
 * class GleanTelemetry : RemoteSettingsTelemetry {
 * override fun report_uptake(eventExtras: UptakeEventExtras) {
 * RSMetrics.uptakeRemotesettings.record(eventExtras)
 * }
 * }
 *
 * service.setTelemetry(GleanTelemetry())
 * ```
