                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_remote_settings_fn_free_remotesettingstelemetry(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_remote_settings_fn_clone_remotesettingstelemetry(handle, status)
        }
    }

    
    /**
     * Report uptake event.
     */override fun `reportUptake`(`extras`: UptakeEventExtras)
        = 
    callWithHandle {
