/**
 * Public error class, this is what we return to consumers
 */
sealed class RemoteSettingsException: kotlin.Exception() {
    
    /**
     * Network error while making a remote settings request
     */
    class Network(
        
        val `reason`: kotlin.String
        ) : RemoteSettingsException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The server has asked the client to backoff.
     */
    class Backoff(
        
        val `seconds`: kotlin.ULong
        ) : RemoteSettingsException() {
        override val message
            get() = "seconds=${ `seconds` }"
    }
    
    class Other(
        
        val `reason`: kotlin.String
        ) : RemoteSettingsException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RemoteSettingsException> {
        override fun lift(error_buf: RustBuffer.ByValue): RemoteSettingsException = FfiConverterTypeRemoteSettingsError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeRemoteSettingsError : FfiConverterRustBuffer<RemoteSettingsException> {
    override fun read(buf: ByteBuffer): RemoteSettingsException {
        

        return when(buf.getInt()) {
            1 -> RemoteSettingsException.Network(
                FfiConverterString.read(buf),
                )
            2 -> RemoteSettingsException.Backoff(
                FfiConverterULong.read(buf),
                )
            3 -> RemoteSettingsException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RemoteSettingsException): ULong {
        return when(value) {
            is RemoteSettingsException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is RemoteSettingsException.Backoff -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterULong.allocationSize(value.`seconds`)
            )
            is RemoteSettingsException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: RemoteSettingsException, buf: ByteBuffer) {
        when(value) {
            is RemoteSettingsException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is RemoteSettingsException.Backoff -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`seconds`, buf)
                Unit
            }
            is RemoteSettingsException.Other -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



