public object FfiConverterTypeRsJsonObject: FfiConverter<RsJsonObject, RustBuffer.ByValue> {
    override fun lift(value: RustBuffer.ByValue): RsJsonObject {
        val builtinValue = FfiConverterString.lift(value)
